    request_queue = deque()

    def add_to_queue(request):
        request_queue.append(request)

    def remove_from_queue():
        if request_queue:
            return request_queue.popleft()
        else:
            return None

    # The secret function to check if the first argument is 'candle_lantern'
    def is_candle_lantern(ip):
        return ip.lower() == 'candle_lantern'

